// Renders the pull-request body Roster opens when it promotes a setup (DESIGN.md §"Act":
// "a PR with setups/<id>.json, the rules file, the review summary, an evidence table, ...").
//
// Pure and total: the body is built only from the input it is given. Every number printed is
// derived from that input — the task counts and the costs, to two decimals — and nothing is
// described with a judgement word. No "significant", no "best": the PR states what was measured
// and the evidence level it was measured at (DESIGN.md §"Overview": "a setup is never called
// 'worse' on level A alone. Every page prints the evidence level next to every claim.").

/** The levels a promotion can rest on: B is a controlled replay, C is a pre-registered forward run. */
export type PromotionEvidence = "B" | "C";

const EVIDENCE_SOURCE: Record<PromotionEvidence, string> = {
  B: "controlled replay",
  C: "pre-registered forward run",
};

export interface PrTask {
  id: string;
  incumbentPass: boolean;
  candidatePass: boolean;
  /** Candidate cost for this task, or null when the cost is unknown. */
  costUsd: number | null;
  traceUrl?: string;
  entireUrl?: string;
}

export interface PrRejection {
  candidate: string;
  reasons: string[];
}

export interface PrBodyInput {
  repo: string;
  incumbent: string;
  promoted: string;
  tasks: PrTask[];
  rejected: PrRejection[];
  evidenceLevel: PromotionEvidence;
}

const PASS = "✓";
const FAIL = "✗";

/** Cost to two decimals, or "n/a" when the input carries no number. */
const cost = (usd: number | null): string => (usd === null ? "n/a" : usd.toFixed(2));

const mark = (pass: boolean): string => (pass ? PASS : FAIL);

/** Markdown links recorded for one task, empty when it carries neither url. */
function taskLinks(t: PrTask): string[] {
  const links: string[] = [];
  if (t.traceUrl) links.push(`[trace](${t.traceUrl})`);
  if (t.entireUrl) links.push(`[entire](${t.entireUrl})`);
  return links;
}

export function renderPrBody(input: PrBodyInput): string {
  const { repo, incumbent, promoted, tasks, rejected, evidenceLevel } = input;
  const n = tasks.length;
  const candidatePassed = tasks.filter((t) => t.candidatePass).length;
  const incumbentPassed = tasks.filter((t) => t.incumbentPass).length;

  const linked = tasks.map((t) => ({ id: t.id, links: taskLinks(t) })).filter((l) => l.links.length > 0);

  const lines = [
    "## Summary",
    "",
    `Promotes setup \`${promoted}\` over the incumbent \`${incumbent}\` in \`${repo}\`.`,
    "",
    `- Evidence level: ${evidenceLevel} (${EVIDENCE_SOURCE[evidenceLevel]})`,
    `- ${candidatePassed} of ${n} tasks passed (incumbent ${incumbentPassed} of ${n})`,
    "",
    "## Evidence",
    "",
    `| Task | Incumbent \`${incumbent}\` | Candidate \`${promoted}\` | Cost (USD) |`,
    "| --- | :---: | :---: | ---: |",
    ...tasks.map((t) => `| \`${t.id}\` | ${mark(t.incumbentPass)} | ${mark(t.candidatePass)} | ${cost(t.costUsd)} |`),
    "",
    "## Rejected candidates",
    "",
    ...(rejected.length
      ? rejected.flatMap((r) => [
          `### \`${r.candidate}\``,
          "",
          ...(r.reasons.length ? r.reasons.map((reason) => `- ${reason}`) : ["None"]),
          "",
        ])
      : ["None", ""]),
    "## Links",
    "",
    ...(linked.length ? linked.map((l) => `- \`${l.id}\`: ${l.links.join(", ")}`) : ["None"]),
    "",
  ];
  return lines.join("\n");
}

